import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import express from "express";
import swaggerUi from "swagger-ui-express";
import { errorHandler } from "./middlewares/errorHandler.js";
import indexRouter from "./routes/index.js";

const app = express();

app.use(express.json());
app.use("/api", indexRouter);

// API docs at /api/docs, generated by `npm run swagger`
const swaggerPath = path.join(process.cwd(), "swagger_output.json");

if (existsSync(swaggerPath)) {
  const swaggerDocument: unknown = JSON.parse(
    readFileSync(swaggerPath, "utf-8"),
  );
  app.use(
    "/api/docs",
    swaggerUi.serve,
    swaggerUi.setup(swaggerDocument as swaggerUi.JsonObject),
  );
}

app.use(errorHandler);

export default app;
